mapper.select:
SELECT PERMISSION_NAME
FROM AUTHORITY
WHERE MEMBER_NUMBER = #{memberNumber}

SELECT DEFAULT_PERMISSION_NAME
FROM POSITION
WHERE POSITION_CODE = #{positionCode}

mapper.insert:
INSERT INTO MEMBER (
    MEMBER_NUMBER
    , MEMBER_ID
    , MEMBER_PASSWORD
    , MEMBER_NAME
    , MEMBER_PHONE_NUMBER
    , ACCOUNT_STATUS
    , MEMBER_STATUS
)
VALUES (
    #{memberNumber}
    , #{memberId}
    , #{memberPassword}
    , #{memberName}
    , #{memberPhoneNumber}
    , #{accountStatus}
    , #{memberStatus}
)

INSERT INTO EMPLOYEE (
    MEMBER_NUMBER
    , DEPARTMENT_CODE
    , POSITION_CODE
)
VALUES (
    #{memberNumber}
    , #{departmentCode}
    , #{positionCode}
)

INSERT INTO AUTHORITY (
    MEMBER_NUMBER
    , PERMISSION_NAME
)
VALUES (
    #{memberNumber}
    , #{permissionName}
)
